WITH filtered_customers AS (SELECT * FROM customers WHERE (city NOT IN ('Bangkok', 'Chiang Mai', 'Tokyo') AND name LIKE 'No%') OR signup_date BETWEEN '2023-07-09' AND '2024-04-01'), summary AS (SELECT DATE_FORMAT(signup_date, 'yyyy-MM') signup_month, ROUND((100 * SUM(CASE WHEN country = 'DE' THEN 1 ELSE 0 END)) / COUNT(*), 1) pct_de, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(segment))) segment_values FROM filtered_customers GROUP BY DATE_FORMAT(signup_date, 'yyyy-MM')) SELECT signup_month, segment_values FROM summary ORDER BY signup_month DESC
